+// formatDuration formats d with two decimal places and a unit suffix
+// padded to a fixed width, so that decimal points line up when the
+// values are right-aligned in a column.
+func formatDuration(d time.Duration) string {
+	var (
+		value float64
+		unit  string
+	)
+	switch abs := max(d, -d); {
+	case abs >= time.Second:
+		value, unit = d.Seconds(), "s"
+	case abs >= time.Millisecond:
+		value, unit = float64(d)/float64(time.Millisecond), "ms"
+	case abs >= time.Microsecond:
+		value, unit = float64(d)/float64(time.Microsecond), "µs"
+	default:
+		value, unit = float64(d), "ns"
+	}
+	return fmt.Sprintf("%.2f%-2s", value, unit)
+}
