+
+// SetImportContext configures opts to resolve imports using the given import context
+// (see resources.Copy) before falling back to the default import resolution.
+func (opts *Options) SetImportContext(ctx context.Context, importContext resource.ResourceGetter, dm identity.Manager) error {
+	if importContext == nil {
+		return nil
+	}
+	if opts.ImportOnResolveFunc != nil || opts.ImportOnLoadFunc != nil {
+		return errors.New("import context cannot be combined with custom import resolvers")
+	}
+	if dm == nil {
+		dm = identity.NopManager
+	}
+
+	importResource := hmaps.NewCache[string, resource.Resource]()
+
+	opts.ImportOnResolveFunc = func(imp string, args api.OnResolveArgs) string {
+		if args.Namespace == "file" {
+			// Imported from a file not in /assets, e.g. in node_modules.
+			return ""
+		}
+		var resolved resource.Resource
+		if strings.HasPrefix(imp, ".") {
+			if importer, ok := strings.CutPrefix(args.Importer, PrefixHugoVirtual); ok {
+				// Relative import from a resource in the import context.
+				resolved = ResolveResource(path.Join(path.Dir(importer), imp), importContext)
+			} else if args.Importer != stdinImporter {
+				// Relative import from a file in /assets, resolve it relative to that file.
+				return ""
+			}
+		}
+		if resolved == nil {
+			resolved = ResolveResource(imp, importContext)
+		}
+		if resolved == nil {
+			return ""
+		}
+		dm.AddIdentity(identity.FirstIdentity(resolved))
+		resolvedPath := PrefixHugoVirtual + resources.InternalResourceTargetPath(resolved)
+		importResource.Set(resolvedPath, resolved)
+		return resolvedPath
+	}
+
+	opts.ImportOnLoadFunc = func(args api.OnLoadArgs) (string, error) {
+		r, found := importResource.Get(args.Path)
+		if !found {
+			return "", nil
+		}
+		content, err := resources.InternalResourceSourceContent(ctx, r)
+		if err != nil {
+			return "", fmt.Errorf("failed to read import %q: %w", resources.InternalResourceSourcePathBestEffort(r), err)
+		}
+		return content, nil
+	}
+
+	opts.ErrorMessageResolveFunc = func(msg api.Message) *ErrorMessageResolved {
+		if msg.Location == nil {
+			return nil
+		}
+		r, found := importResource.Get(strings.TrimPrefix(msg.Location.File, NsHugoImportResolveFunc+":"))
+		if !found {
+			return nil
+		}
+		var contentr hugio.ReadSeekCloser
+		if cp, ok := r.(hugio.ReadSeekCloserProvider); ok {
+			contentr, _ = cp.ReadSeekCloser()
+		}
+		return &ErrorMessageResolved{
+			Content: contentr,
+			Path:    resources.InternalResourceSourcePathBestEffort(r),
+			Message: msg.Text,
+		}
+	}
+
+	opts.ResolveSourceMapSource = func(s string) string {
+		if r, found := importResource.Get(s); found {
+			if ss := resources.InternalResourceSourcePath(r); ss != "" {
+				return ss
+			}
+			return PrefixHugoMemory + s
+		}
+		return ""
+	}
+
+	return nil
+}
