+
+package resources
+
+import (
+	"context"
+	"fmt"
+	"strings"
+
+	"github.com/gohugoio/hugo/common/hashing"
+	"github.com/gohugoio/hugo/common/hreflect"
+	"github.com/gohugoio/hugo/identity"
+	"github.com/gohugoio/hugo/resources/resource"
+)
+
+// ImportContext holds a set of resources that can be used to resolve
+// imports (e.g. CSS @import, JS import) when building a resource.
+type ImportContext struct {
+	// The resource getter used to resolve imports.
+	Getter resource.ResourceGetter
+
+	// A key identifying this import context.
+	// Used to separate resources with different import contexts in the caches.
+	Key string
+}
+
+// CopyOptions holds the options for Copy.
+type CopyOptions struct {
+	// The target path of the copy.
+	// If empty, the target path of the source resource is used.
+	TargetPath string
+
+	// The import context to attach to the copy.
+	// If nil, any import context on the source resource is preserved.
+	ImportContext *ImportContext
+}
+
+// NewImportContext creates a new ImportContext from v, which can be a
+// Resource, a Page (or anything else providing Resources), a ResourceGetter
+// (e.g. from Resources.Mount) or a slice of any of these.
+// The first match wins.
+func NewImportContext(v any) (*ImportContext, error) {
+	if v == nil {
+		return nil, nil
+	}
+	var keys []string
+	var collect func(v any) error
+	collect = func(v any) error {
+		switch vv := v.(type) {
+		case nil:
+			return nil
+		case interface{ Key() string }:
+			// Resource, Page, mounted resources.
+			key := vv.Key()
+			if r, ok := v.(resource.Resource); ok && InternalResourceSourcePath(r) == "" {
+				// In-memory resources (e.g. from resources.FromString) with the
+				// same target path may have different content.
+				content, err := InternalResourceSourceContent(context.Background(), r)
+				if err != nil {
+					return fmt.Errorf("importContext: %w", err)
+				}
+				key += "_" + hashing.HashStringHex(content)
+			}
+			keys = append(keys, key)
+		case identity.IdentityProvider:
+			keys = append(keys, vv.GetIdentity().IdentifierBase())
+		case resource.ResourcesProvider:
+			for _, r := range vv.Resources() {
+				if err := collect(r); err != nil {
+					return err
+				}
+			}
+		default:
+			s, ok := hreflect.ToSliceAny(v)
+			if !ok {
+				return fmt.Errorf("importContext: unsupported type %T", v)
+			}
+			for _, e := range s {
+				if err := collect(e); err != nil {
+					return err
+				}
+			}
+		}
+		return nil
+	}
+	if err := collect(v); err != nil {
+		return nil, err
+	}
+
+	if len(keys) == 0 {
+		return nil, nil
+	}
+
+	return &ImportContext{
+		Getter: resource.NewCachedResourceGetter(v),
+		Key:    hashing.HashStringHex(strings.Join(keys, "|")),
+	}, nil
+}
+
+type importContextProvider interface {
+	importContext() *ImportContext
+}
+
+// InternalResourceImportContext is used internally to get the import context set on r using resources.Copy.
+// It returns nil if no import context is set.
+func InternalResourceImportContext(r resource.Resource) resource.ResourceGetter {
+	if p, ok := r.(importContextProvider); ok {
+		if ic := p.importContext(); ic != nil {
+			return ic.Getter
+		}
+	}
+	return nil
+}
