+import (
+	"fmt"
+	"path"
+	"strings"
+
+	"github.com/gohugoio/hugo/resources/resource"
+)
+
+// ImportContextURLPrefix is used to mark imports resolved from an import context (see resources.Copy).
+const ImportContextURLPrefix = "hugo-ic:/"
+
+// ResolveFromImportContext resolves the Sass import path p, which may be relative to importer
+// if importer is a URL created by this function, using importContext, trying the
+// common Sass partial and extension variants.
+// It returns the resolved resource and its URL (prefixed with ImportContextURLPrefix),
+// or nil if not found.
+func ResolveFromImportContext(importContext resource.ResourceGetter, p, importer string, includeCSS bool) (resource.Resource, string) {
+	if importContext == nil {
+		return nil, ""
+	}
+
+	var candidates []string
+	if importerPath, ok := strings.CutPrefix(importer, ImportContextURLPrefix); ok && !strings.HasPrefix(p, "/") {
+		candidates = append(candidates, path.Join(path.Dir(importerPath), p))
+	}
+	if after, ok := strings.CutPrefix(p, ImportContextURLPrefix); ok {
+		// Already resolved relative to an import context URL.
+		p = after
+	}
+	candidates = append(candidates, path.Clean(strings.TrimPrefix(p, "/")))
+
+	for _, candidate := range candidates {
+		dir, name := path.Split(candidate)
+
+		var namePatterns []string
+		if strings.Contains(name, ".") {
+			namePatterns = []string{"_%s", "%s"}
+		} else if strings.HasPrefix(name, "_") {
+			namePatterns = []string{"_%s.scss", "_%s.sass"}
+			if includeCSS {
+				namePatterns = append(namePatterns, "_%s.css")
+			}
+		} else {
+			namePatterns = []string{
+				"_%s.scss", "%s.scss",
+				"_%s.sass", "%s.sass",
+			}
+			if includeCSS {
+				namePatterns = append(namePatterns, "_%s.css", "%s.css")
+			}
+			namePatterns = append(namePatterns,
+				"%s/_index.scss", "%s/_index.sass",
+				"%s/index.scss", "%s/index.sass",
+			)
+		}
+
+		name = strings.TrimPrefix(name, "_")
+
+		for _, namePattern := range namePatterns {
+			nameToCheck := path.Join(dir, fmt.Sprintf(namePattern, name))
+			if r := importContext.Get(nameToCheck); r != nil {
+				return r, ImportContextURLPrefix + strings.TrimPrefix(nameToCheck, "/")
+			}
+		}
+	}
+
+	return nil, ""
+}
