+
+func TestCSSBuildImportContext(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+disableKinds = ["taxonomy", "term", "page", "section", "rss", "sitemap"]
+-- assets/css/main.css --
+@import "foo.css" screen;
+@import "bar.css" print;
+@import "baz.css";
+.main { color: red; }
+-- assets/css/baz.css --
+.baz { color: from-assets; }
+-- assets/css/other/qux.css --
+.qux { color: from-mount; }
+-- layouts/home.html --
+{{ $foo := resources.FromString "foo.css" "body { color: blue; }" }}
+{{ $bar := resources.FromString "bar.css" "@import \"nested.css\";\nbody { color: green; }" }}
+{{ $nested := resources.FromString "nested.css" ".nested { color: black; }" }}
+{{ $main := resources.Get "css/main.css" }}
+{{ $copy := $main | resources.Copy (dict "importContext" (slice $foo $bar $nested)) }}
+{{ with $copy | css.Build }}Copy: {{ .RelPermalink }}|{{ .Content | safeCSS }}|{{ end }}
+{{ $copy2 := resources.Copy (dict "targetPath" "css/main2.css" "importContext" (slice $foo $bar $nested)) $main }}
+{{ with $copy2 | css.Build }}Copy2: {{ .RelPermalink }}|{{ end }}
+{{ $mounted := resources.Match "css/other/*.css" }}
+{{ $main3 := resources.FromString "css/main3.css" "@import \"mnt/qux.css\";" }}
+{{ with $main3 | resources.Copy (dict "importContext" ($mounted.Mount "/css/other" "mnt")) | css.Build }}Mounted: {{ .Content | safeCSS }}|{{ end }}
+`
+
+	b := hugolib.Test(t, files, hugolib.TestOptOsFs())
+
+	b.AssertFileContent("public/index.html",
+		"Copy: /css/main.css|",
+		"@media screen {\n  body {\n    color: blue;\n  }\n}",
+		"@media print {\n  .nested {\n    color: black;\n  }\n}",
+		"@media print {\n  body {\n    color: green;\n  }\n}",
+		".baz {\n  color: from-assets;\n}",
+		"Copy2: /css/main2.css|",
+		"Mounted:", ".qux {\n  color: from-mount;\n}",
+	)
+	b.AssertPublishDir("css/main.css", "css/main2.css")
+
+	// The import context must not leak into a build of the original resource.
+	files += `
+{{ with $main | css.Build }}NoContext: {{ .RelPermalink }}|{{ end }}
+`
+	b, err := hugolib.TestE(t, files, hugolib.TestOptOsFs())
+	b.Assert(err, qt.IsNotNil)
+	b.Assert(err.Error(), qt.Contains, `Could not resolve "foo.css"`)
+}
+
+func TestResourcesCopyImportContextInvalid(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+-- layouts/home.html --
+{{ $main := resources.FromString "main.css" "@import \"foo.css\";" }}
+{{ $main | resources.Copy (dict "importContext" 32) }}
+`
+	b, err := hugolib.TestE(t, files)
+	b.Assert(err, qt.IsNotNil)
+	b.Assert(err.Error(), qt.Contains, "importContext: unsupported type int")
+
+	files = strings.ReplaceAll(files, `(dict "importContext" 32)`, `(dict "foo" 32)`)
+	b, err = hugolib.TestE(t, files)
+	b.Assert(err, qt.IsNotNil)
+	b.Assert(err.Error(), qt.Contains, `unknown option "foo"`)
+}
+
+func TestCSSBuildImportContextRebuild(t *testing.T) {
+	t.Parallel()
+
+	files := `
