+// fragmentsToKeywords returns the keywords to index and match for the given fragments.
+// All fragment identifiers are returned as FragmentKeyword.
+// If Tokenize is enabled, the words in each heading title are also returned
+// as FragmentTokenKeyword, each word only once.
+func (cfg IndexConfig) fragmentsToKeywords(fragments *tableofcontents.Fragments) []Keyword {
+	if fragments == nil {
+		return nil
+	}
+	keywords := make([]Keyword, 0, len(fragments.Identifiers))
+	for _, id := range fragments.Identifiers {
+		keywords = append(keywords, FragmentKeyword(id))
+	}
+	if !cfg.Tokenize {
+		return keywords
+	}
+
+	seen := make(map[string]bool)
+	// Only headings are tokenized; other fragments, e.g. definition terms,
+	// are matched by their identifier only.
+	headings := fragments.Headings.FilterBy(func(*tableofcontents.Heading) bool { return true })
+	for _, h := range headings {
+		for _, token := range cfg.tokenizeHeadingTitle(h.Title) {
+			if seen[token] {
+				continue
+			}
+			seen[token] = true
+			keywords = append(keywords, FragmentTokenKeyword(token))
+		}
+	}
+
+	return keywords
