+func TestRelatedFragmentsTokenize(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+baseURL = "http://example.com/"
+disableKinds = ["taxonomy", "term", "RSS", "sitemap", "robotsTXT"]
+[markup.goldmark.parser]
+autoDefinitionTermID = true
+[related]
+  includeNewer = true
+  threshold = 20
+  toLower = true
+[[related.indices]]
+  name = 'pagerefs'
+  type = 'fragments'
+  applyFilter = true
+  tokenize = TOKENIZE
+  weight = 100
+-- content/p1.md --
+---
+title: p1
+---
+## Installing Hugo on Linux
+-- content/p2.md --
+---
+title: p2
+---
+## Running *hugo* & friends
+
+## Unrelated section
+-- content/p3.md --
+---
+title: p3
+---
+## Something else
+-- content/p4.md --
+---
+title: p4
+---
+Installing Hugo
+: A definition term.
+-- content/p5.md --
+---
+title: p5
+pagerefs: ['something-else']
+---
+## Nothing
+-- layouts/single.html --
+{{ $related := site.RegularPages.Related . }}
+Related: {{ range $related }}{{ .Title }}: {{ range .HeadingsFiltered }}{{ .Title }}|{{ end }};{{ end }}::END
+`
+
+	b := hugolib.Test(t, strings.ReplaceAll(files, "TOKENIZE", "true"))
+
+	// p1 and p2 share the word "hugo" in their heading titles.
+	b.AssertFileContent("public/p1/index.html", "Related: p2: Running &lt;em&gt;hugo&lt;/em&gt; &amp;amp; friends|;::END")
+	b.AssertFileContent("public/p2/index.html", "Related: p1: Installing Hugo on Linux|;::END")
+	// Definition terms are not tokenized, so "Installing Hugo" in p4 matches nothing.
+	b.AssertFileContent("public/p4/index.html", "Related: ::END")
+	// Exact identifier matching still works.
+	b.AssertFileContent("public/p5/index.html", "Related: p3: Something else|;::END")
+
+	b = hugolib.Test(t, strings.ReplaceAll(files, "TOKENIZE", "false"))
+
+	b.AssertFileContent("public/p1/index.html", "Related: ::END")
+	b.AssertFileContent("public/p2/index.html", "Related: ::END")
+	b.AssertFileContent("public/p5/index.html", "Related: p3: Something else|;::END")
+}

