+// Verify the JS context escaping fixes synced from Go 1.27's html/template.
+func TestSecurityJSRegexpContextEscaping(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+disableKinds = ["taxonomy", "term", "page", "rss", "sitemap", "404"]
+-- content/_index.md --
+---
+title: "Home"
+params:
+  re: "/;alert(1)//"
+  user: "1;pwned=1;0"
+  dot: "a.b"
+  tmpl: "x/.exec(alert(1))}"
+---
+-- layouts/home.html --
+<script>function* rules(){yield /{{ .Params.re }}/g}</script>
+<script>const pct = bond.yield / 100; const user1 = {{ .Params.user }};</script>
+<script>class Bond { #yield = 4; pct() { return this.#yield / 100; } } const user2 = {{ .Params.user }};</script>
+<script>if(true){/{{ .Params.dot }}/g.test("x")}</script>
+<script>const s = §§${1}${/{{ .Params.tmpl }}/g}§§</script>
+`
+
+	b := hugolib.Test(t, files)
+
+	b.AssertFileContent("public/index.html",
+		`yield /\/;alert\(1\)\/\//g`,
+		`const user1 = "1;pwned=1;0";`,
+		`const user2 = "1;pwned=1;0";`,
+		`if(true){/a\.b/g.test("x")}`,
+		"const s = `${1}${/x\\/\\.exec\\(alert\\(1\\)\\)\\}/g}`",
+	)
+}
